"import express, { Request } from 'express';
import { createServer } from 'node:http';
import { config } from './config.js';
import { initDb } from './db.js';
import webhookRoutes from './routes/webhookRoutes.js';
import graderRoutes from './routes/graderRoutes.js';

// Extend Express Request to hold rawBody buffer
declare global {
  namespace Express {
    interface Request {
      rawBody?: Buffer;
    }
  }
}

const app = express();

// Parse JSON while keeping raw body buffer for HMAC signature verification
app.use(
  express.json({
    verify: (req: Request, _res, buf) => {
      req.rawBody = buf;
    },
  })
);

// Health check endpoint
app.get('/healthz', (_req, res) => {
  res.json({ ok: true });
});

// Mount Routes
app.use('/webhooks', webhookRoutes);
app.use('/__grader', graderRoutes);

// Plain HTTP server for WebSocket readiness
const server = createServer(app);

async function start() {
  await initDb();

  server.listen(config.port, () => {
    console.log(`server on http://localhost:${config.port}`);
  });
}

start().catch((err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});
"

